from typing import Set
from random import choice

def load_dictionary() -> Set[str]:
    # This is a placeholder, replace with actual dictionary loading code
    dictionary = set(['HELLO', 'WORLD', 'PYTHON', 'CODER', 'PROGRAM'])
    return dictionary


def is_valid_word(word: str) -> bool:
    dictionary = load_dictionary()
    return word.isalpha() and len(word) == 5 and word.upper() in dictionary


def get_random_word() -> str:
    dictionary = load_dictionary()
    return choice(list(dictionary))


def normalize_word(word: str) -> str:
    return word.strip().upper()
